with
UserStats as (
    select
        u.Id,
        u.DisplayName,
        u.Reputation,
        CountDistinctPosts = (select count(*) from Posts p where p.OwnerUserId = u.Id),
        LastActive = u.LastAccessDate,
        DistUrls = coalesce(case when fp.first_url is not null then jsonb_agg(distinct fp.first_url)::text else '[]'::text end
                              , '[]')
    from
        Users u
     left join lateral (
           select substring(trim(scene) from '^https?://[^/ ]+')
            as first_url
          from unnest(string_to_array(coalesce(u.WebsiteUrl, ''), ',')) apl(nml)
